# Paste into Azure portal > VM > Run command > RunShellScript. Runs as root.
# Adds the SIZED book (commit fb712e0) to the paper bot. No backslashes on purpose (doc 09).
set -e
APP=/opt/forexbot
cd $APP
STAMP=$(date -u +%Y%m%d-%H%M%S)
cp blend_paper.py logs/blend_paper.py.bak-$STAMP
echo "backup: logs/blend_paper.py.bak-$STAMP"
echo '' | base64 -d | gunzip > blend_paper.py.new
echo "22a66a41c540b1e2a171a8ac219bcebbab28bc722ae2e8e430cc00a4bcece6b8  blend_paper.py.new" | sha256sum -c -
./.venv/bin/python -c "import ast; ast.parse(open('blend_paper.py.new').read()); print('syntax ok')"
OWNER=$(stat -c %U blend_paper.py)
mv blend_paper.py.new blend_paper.py
chown $OWNER:$OWNER blend_paper.py
systemctl restart blend-paper
echo "restarted; waiting 90s for the first cycle"
sleep 90
systemctl is-active blend-paper
journalctl -u blend-paper -n 80 --no-pager | grep -E "SIZED|TIGHT book forked|error|Traceback" || true
sudo -u $OWNER ./.venv/bin/python blend_paper.py --status | sed -n '/SIZED BOOK/,/watch/p'
